import re


_VERSION_RE = re.compile(r"^(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)$")
_HEADER_RE = re.compile(
    r"^(?P<type>[a-z]+)(?:\((?P<scope>[^()]+)\))?(?P<breaking>!)?: .*$"
)


def next_version(current, commits):
    """The version after `current`, decided by the commit messages. See TASK.md."""
    match = _VERSION_RE.fullmatch(current)
    if match is None:
        raise ValueError("invalid version")

    major, minor, patch = (int(part) for part in match.groups())
    strongest = 0  # 0: none, 1: fix, 2: feature, 3: breaking

    for message in commits:
        lines = message.splitlines()
        if not lines:
            continue
        header = _HEADER_RE.fullmatch(lines[0])
        if header is None:
            continue

        commit_type = header.group("type")
        if header.group("breaking") or any(
            line.startswith(("BREAKING CHANGE: ", "BREAKING-CHANGE: "))
            for line in lines[1:]
        ):
            change = 3
        elif commit_type == "feat":
            change = 2
        elif commit_type == "fix":
            change = 1
        else:
            change = 0
        strongest = max(strongest, change)

    if strongest == 3:
        if major == 0:
            minor += 1
            patch = 0
        else:
            major += 1
            minor = patch = 0
    elif strongest == 2:
        if major == 0:
            patch += 1
        else:
            minor += 1
            patch = 0
    elif strongest == 1:
        patch += 1

    return f"{major}.{minor}.{patch}"
